def test_multiple_visits_share_capacity_up_to_the_last_slot():
    full = {date(2024, 1, 31): 0} | {date(2024, 2, day): 0 for day in range(1, 29)}
    arguments = {
        "first_day": date(2024, 1, 31),
        "offsets_months": [0, 1],
        "hour": 10,
        "minute": 0,
        "timezone": "America/New_York",
    }

    two_slots = full | {date(2024, 2, 29): 2}
    one_slot = full | {date(2024, 2, 29): 1}
    two_slots_before, one_slot_before = two_slots.copy(), one_slot.copy()

    both_fit = plan_visits(capacity=two_slots, **arguments)
    second_moves = plan_visits(capacity=one_slot, **arguments)

    assert [visit["local"][:10] for visit in both_fit] == ["2024-02-29", "2024-02-29"]
    assert [visit["local"][:10] for visit in second_moves] == [
        "2024-02-29",
        "2024-03-01",
    ]
    assert two_slots == two_slots_before
    assert one_slot == one_slot_before


