def test_booking_sequential_calls_contend_for_slots():
    capacity = {date(2024, 7, 1): 2, date(2024, 7, 2): 1}

    days = []
    balances = []
    for _ in range(4):
        [visit] = book(capacity)
        days.append(visit["local"][:10])
        balances.append(dict(capacity))

    assert days == ["2024-07-01", "2024-07-01", "2024-07-02", "2024-07-03"]
    assert balances == [
        {date(2024, 7, 1): 1, date(2024, 7, 2): 1},
        {date(2024, 7, 1): 0, date(2024, 7, 2): 1},
        {date(2024, 7, 1): 0, date(2024, 7, 2): 0},
        # 3 July is unlisted: unconstrained, and never inserted.
        {date(2024, 7, 1): 0, date(2024, 7, 2): 0},
    ]


def test_booking_returns_the_plan_and_commits_within_plan_contention():
    closed = {date(2024, 1, 31)} | {date(2024, 2, day) for day in range(1, 29)}
    closed_before = closed.copy()
    capacity = {date(2024, 2, 29): 1, date(2024, 3, 1): 5, date(2024, 3, 2): 3}
    arguments = {
        "first_day": date(2024, 1, 31),
        "offsets_months": [0, 1],
        "hour": 10,
        "minute": 0,
        "timezone": "America/New_York",
        "closed_days": closed,
    }
    expected = plan_visits(capacity=dict(capacity), **arguments)

    visits = book(capacity, **arguments)

    assert visits == expected
    assert [visit["local"][:10] for visit in visits] == ["2024-02-29", "2024-03-01"]
    assert capacity == {
        date(2024, 2, 29): 0,
        date(2024, 3, 1): 4,
        date(2024, 3, 2): 3,
    }
    assert closed == closed_before


def test_booking_rolls_back_when_a_later_visit_cannot_be_scheduled():
    capacity = {date(2024, 7, 1): 2}
    book(capacity)
    assert capacity == {date(2024, 7, 1): 1}

    closed = {date(2024, 8, 1) + timedelta(days=days) for days in range(367)}
    with pytest.raises(ValueError, match="UNSCHEDULABLE"):
        book(capacity, offsets_months=[0, 1], closed_days=closed)

    # The failed plan reserved nothing; the earlier booking stays committed.
    assert capacity == {date(2024, 7, 1): 1}


