def test_booking_ineligible_subject_reports_ordered_reasons_and_reserves_nothing():
    subject = make_subject()
    subject.update(flags=["PRIOR"], labs={"A": 0, "Z": 15})
    protocol = make_protocol()
    subject_before, protocol_before = deepcopy(subject), deepcopy(protocol)
    capacity = {date(2024, 7, 1): 1}

    with pytest.raises(ValueError) as raised:
        book(capacity, subject=subject, protocol=protocol)
    assert str(raised.value) == "INELIGIBLE:EXCLUSION_PRIOR,LAB_A_LOW"

    # Eligibility is decided before planning, so it wins over bad plan input.
    with pytest.raises(ValueError, match="^INELIGIBLE:"):
        book(capacity, subject=subject, protocol=protocol, timezone="Not/A_Real_Zone")

    assert capacity == {date(2024, 7, 1): 1}
    assert subject == subject_before
    assert protocol == protocol_before


